parameters.jsCode:
// Risk factors drawn from the EDPB guidelines on personal data breach notification (WP250 rev.01) and
// from Art. 33 and 34 themselves. severity high means the breach is likely to be a high risk to people,
// which is the Art. 34 test for telling the people affected. Edit these rows in breach_risk_factors
// after the first run; the table is the policy, not the code.
const rows = [
  ['special_categories', 'Special category or criminal data', 'Health, biometric, genetic, racial or ethnic origin, political opinion, religion, trade union membership, sex life or criminal convictions were involved.', 'health|medical|diagnos|biometric|genetic|religio|ethnic|sexual|political|trade union|criminal|conviction|patient record', 'special_categories', 'high'],
  ['financial_data', 'Financial or payment data', 'Bank details, card numbers, salary or anything that lets someone take money or obtain credit in the person name.', 'bank account|iban|card number|credit card|payment detail|salary|payroll|invoice detail|sort code', 'financial_data', 'high'],
  ['credentials_exposed', 'Credentials or authentication data', 'Passwords, hashes, session tokens, API keys or password reset links were exposed, so accounts can be taken over.', 'password|passwd|hash|token|api key|credential|session cookie|reset link|mfa|otp', 'credentials_exposed', 'high'],
  ['identity_theft_risk', 'Enough data to impersonate someone', 'A combination such as full name with date of birth, national id, passport or address that supports identity theft.', 'passport|national id|social security|aadhaar|date of birth|identity document|driving licence|driving license|tax number', 'identity_theft_risk', 'high'],
  ['vulnerable_subjects', 'Vulnerable people affected', 'Children, patients, employees, elderly people or anyone in an imbalance of power with the organisation.', 'child|minor|pupil|student|patient|employee|elderly|asylum|refugee|disab', 'vulnerable_subjects', 'high'],
  ['large_number', 'Many people affected', 'A large number of data subjects, which raises both the likelihood and the severity of harm.', 'thousands|millions|entire database|all customers|all employees|full export|whole table', 'affected_count', 'normal'],
  ['unencrypted', 'Data was readable', 'The data was not encrypted, or the key was exposed with it, so anyone holding it can read it.', 'unencrypted|not encrypted|plain text|plaintext|cleartext|no encryption|key was included', 'encryption_state', 'normal'],
  ['recipient_unknown', 'Recipient unknown or uncontrolled', 'The data reached someone who cannot be identified or who will not confirm deletion, including a public location.', 'public|internet|published|anyone could|unknown recipient|posted online|search engine|shared link', 'recipient_known', 'normal'],
  ['availability_loss', 'Data lost or unavailable', 'Data was destroyed, encrypted by an attacker or otherwise cannot be reached, which is a breach even when nobody read it.', 'ransomware|deleted|destroyed|corrupt|unrecoverable|no backup|locked out|wiped', 'availability_loss', 'normal'],
  ['ongoing_exposure', 'Exposure has not been stopped', 'The data is still reachable, or it is not known whether it is, so harm can still be happening now.', 'still exposed|not yet closed|still open|ongoing|cannot confirm|unclear whether', 'contained', 'high']
];
return rows.map(r => ({ json: { factor_key: r[0], title: r[1], description: r[2], keywords: r[3], form_field: r[4], severity: r[5] } }));

const form = $('Report A Breach').first().json;
const policy = $('Set Breach Policy').first().json;
const factors = $input.all().map(i => i.json).filter(f => f && f.factor_key);
const deadlineHours = Number(policy.deadline_hours) || 72;
const minChars = Number(policy.min_description_chars) || 60;
const highRiskAt = Number(policy.high_risk_threshold) || 1;
const largeAt = Number(policy.large_number_threshold) || 1000;

const text = [form.what_happened, form.data_involved, form.who_is_affected].map(v => String(v || '')).join(' \n ');
const lower = text.toLowerCase();
const yes = v => String(v || '').trim().toLowerCase() === 'yes';
const no = v => String(v || '').trim().toLowerCase() === 'no';
const unsure = v => String(v || '').trim().toLowerCase() === 'not sure';

// affected_count arrives as free text on the form; read the digits out of it rather than trusting a format
const countDigits = String(form.affected_count || '').replace(/[^0-9]/g, '');
const affected = countDigits ? Number(countDigits) : null;

const met = [];
const unsureKeys = [];
for (const f of factors) {
  const sources = [];
  const field = String(f.form_field || '');
  if (field === 'affected_count') {
    if (affected !== null && affected >= largeAt) sources.push({ source: 'form', evidence: 'affected_count = ' + affected + ', at or above ' + largeAt });
  } else if (field === 'encryption_state') {
    if (/^(no|not encrypted)$/i.test(String(form.encryption_state || '').trim())) sources.push({ source: 'form', evidence: 'the data was not encrypted' });
    else if (unsure(form.encryption_state)) unsureKeys.push(f.factor_key);
  } else if (field === 'recipient_known') {
    if (no(form.recipient_known)) sources.push({ source: 'form', evidence: 'the recipient is not known' });
    else if (unsure(form.recipient_known)) unsureKeys.push(f.factor_key);
  } else if (field === 'contained') {
    if (no(form.contained)) sources.push({ source: 'form', evidence: 'the exposure has not been contained' });
    else if (unsure(form.contained)) unsureKeys.push(f.factor_key);
  } else if (field && yes(form[field])) {
    sources.push({ source: 'form', evidence: field + ' = Yes' });
  } else if (field && unsure(form[field])) {
    unsureKeys.push(f.factor_key);
  }
  const kws = String(f.keywords || '').split('|').map(s => s.trim().toLowerCase()).filter(Boolean);
  const hit = kws.find(k => k && lower.includes(k));
  if (hit) sources.push({ source: 'keyword', evidence: 'the description contains "' + hit + '"' });
  if (sources.length) met.push({ factor_key: f.factor_key, title: f.title, severity: f.severity || 'normal',
                                 source: sources.map(s => s.source).join('+'), evidence: sources.map(s => s.evidence).join('; ') });
}

// the 72 hour clock runs from awareness, not from the breach happening
const detectedRaw = String(form.detected_at || '').trim();
const detected = detectedRaw ? new Date(detectedRaw) : null;
const detectedOk = detected && !isNaN(detected.getTime());
const now = new Date();
const base = detectedOk ? detected : now;
const deadline = new Date(base.getTime() + deadlineHours * 3600 * 1000);
const hoursLeft = Math.round(((deadline.getTime() - now.getTime()) / 3600000) * 10) / 10;

const factorsList = factors.map(f => f.factor_key + ': ' + f.title + ' (' + f.description + ')').join('\n');
const judgePrompt = 'RISK FACTORS:\n' + factorsList + '\n\nALREADY MET (do not repeat): ' + (met.map(m => m.factor_key).join(', ') || 'none') +
  '\n\nBREACH DESCRIPTION:\n' + text +
  '\n\nList any risk factor the description shows but which is not already met. For each give the factor_key and a verbatim quote, at least four words, copied exactly from the BREACH DESCRIPTION. If nothing more is shown, return an empty list.';

return [{ json: {
  breach_id: String($execution.id),
  reported_at: now.toISOString(),
  detected_at: detectedOk ? detected.toISOString() : '',
  detected_ok: detectedOk,
  deadline_at: deadline.toISOString(),
  deadline_hours: deadlineHours,
  hours_left: hoursLeft,
  title: String(form.title || ''),
  reporter: String(form.reporter || ''),
  description: String(form.what_happened || ''),
  text,
  factors_loaded: factors.length,
  factor_keys: factors.map(f => f.factor_key),
  factor_titles: Object.fromEntries(factors.map(f => [f.factor_key, f.title])),
  factor_severity: Object.fromEntries(factors.map(f => [f.factor_key, f.severity || 'normal'])),
  met, unsure_keys: unsureKeys,
  affected_count: affected,
  high_risk_threshold: highRiskAt,
  min_description_chars: minChars,
  description_too_short: String(form.what_happened || '').trim().length < minChars,
  judge_prompt: judgePrompt
} }];

const s = $('Score The Breach').first().json;
const item = $input.first().json || {};
const out = item.output && typeof item.output === 'object' ? item.output : null;
const added = [];
const rejected = [];
let judgeStatus, judgeNote = '';
if (out && Array.isArray(out.additional_factors)) {
  judgeStatus = 'answered';
  judgeNote = String(out.note || '');
  const lower = String(s.text || '').toLowerCase();
  for (const a of out.additional_factors) {
    const key = String((a && a.factor_key) || '').trim();
    const quote = String((a && a.quote) || '').trim();
    if (!s.factor_keys.includes(key)) { rejected.push(key + ': unknown factor'); continue; }
    if (s.met.some(m => m.factor_key === key) || added.some(m => m.factor_key === key)) { rejected.push(key + ': already met'); continue; }
    if (quote.length < 12 || !lower.includes(quote.toLowerCase())) { rejected.push(key + ': quote not found in the description'); continue; }
    added.push({ factor_key: key, title: s.factor_titles[key] || key, severity: s.factor_severity[key] || 'normal',
                 source: 'judge', evidence: 'quoted from the report: "' + quote.slice(0, 200) + '"' });
  }
} else {
  judgeStatus = 'did not answer';
  judgeNote = 'the reviewer did not answer' + (item.error ? ': ' + String(item.error.message || item.error).slice(0, 160) : '');
}

const all = s.met.concat(added);
const high = all.filter(m => m.severity === 'high');

// Art. 33: notify the authority unless the breach is unlikely to result in a risk to people.
// Art. 34: also tell the people themselves when the risk to them is high.
let verdict, reason;
if (!s.factors_loaded) {
  verdict = 'INCOMPLETE';
  reason = 'the breach_risk_factors table is empty, so nothing could be assessed; run Set Up Tables first. An empty table is not a finding of no risk';
} else if (s.description_too_short) {
  verdict = 'INCOMPLETE';
  reason = 'the description is shorter than ' + s.min_description_chars + ' characters, which is too little to assess';
} else if (!s.detected_ok) {
  verdict = 'INCOMPLETE';
  reason = 'the date you became aware of the breach could not be read, so the 72 hour deadline cannot be calculated; the clock runs from awareness, not from the incident';
} else if (high.length >= s.high_risk_threshold) {
  verdict = 'NOTIFY_AUTHORITY_AND_SUBJECTS';
  reason = high.length + ' high risk factor(s) and ' + all.length + ' factor(s) in total; Art. 33 requires the supervisory authority and Art. 34 requires the people affected to be told without undue delay';
} else if (all.length > 0) {
  verdict = 'NOTIFY_AUTHORITY';
  reason = all.length + ' risk factor(s) met and none of them high; Art. 33 requires the authority to be told unless the breach is unlikely to result in a risk, and something was found';
} else {
  verdict = 'RECORD_ONLY';
  reason = 'no risk factor was met by the answers or the description; Art. 33(5) still requires the breach to be documented, which this row does. Record only is not the same as no breach';
}

const notifiable = verdict === 'NOTIFY_AUTHORITY' || verdict === 'NOTIFY_AUTHORITY_AND_SUBJECTS';
const lines = all.map(m => '- [' + m.severity + '] ' + m.title + ' [' + m.source + ']: ' + m.evidence);
if (s.unsure_keys.length) lines.push('- Answered "Not sure": ' + s.unsure_keys.join(', ') + ' (not counted; a person has to decide)');
if (rejected.length) lines.push('- Reviewer suggestions not counted: ' + rejected.join('; '));
lines.push('- Reviewer: ' + judgeStatus + (judgeNote ? ' (' + judgeNote.slice(0, 200) + ')' : ''));
const clock = s.detected_ok
  ? 'Aware at ' + s.detected_at + '. Deadline ' + s.deadline_at + ', ' + s.hours_left + ' hours left.'
  : 'No usable awareness time, so no deadline could be set.';
const report = 'Verdict ' + verdict + ': ' + reason + '\n' + clock + '\n' + lines.join('\n');

return [{ json: Object.assign({}, s, {
  factors_all: all,
  factor_count: all.length,
  high_count: high.length,
  factors_met_text: all.map(m => m.factor_key).join(', ') || 'none',
  judge_added_text: added.map(m => m.factor_key).join(', ') || 'none',
  judge_status: judgeStatus, judge_note: judgeNote,
  verdict, verdict_reason: reason, notifiable, report,
  description_excerpt: String(s.description || '').slice(0, 300)
}) }];

const d = $('Combine Into A Verdict').first().json;
const rows = d.factors_all.map(m => ({ json: {
  breach_id: d.breach_id, title: d.title, factor_key: m.factor_key, severity: m.severity,
  source: m.source, evidence: String(m.evidence).slice(0, 400), found_at: d.reported_at } }));
if (!rows.length) rows.push({ json: {
  breach_id: d.breach_id, title: d.title, factor_key: 'none', severity: 'none',
  source: 'rules', evidence: 'no risk factor met; verdict ' + d.verdict, found_at: d.reported_at } });
return rows;

parameters.completionMessage:
=Tell the supervisory authority and the people affected.

{{ $('Combine Into A Verdict').first().json.report }}

The deadline for the authority is {{ $('Combine Into A Verdict').first().json.deadline_at }}. Art. 34 has no fixed hour count: the people affected are told without undue delay. Breach id {{ $('Combine Into A Verdict').first().json.breach_id }} is in breach_register with authority_notified set to no, and the daily watchdog will chase it until you change that to yes. This is a triage aid, not legal advice.

=Tell the supervisory authority.

{{ $('Combine Into A Verdict').first().json.report }}

The deadline is {{ $('Combine Into A Verdict').first().json.deadline_at }}. No high severity factor was found, so Art. 34 notification of the people affected is not indicated by this assessment; that judgement is still yours. Breach id {{ $('Combine Into A Verdict').first().json.breach_id }} is in breach_register with authority_notified set to no. This is a triage aid, not legal advice.

parameters.jsCode:
const policy = $('Set Reminder Policy').first().json;
const warnAt = Number(policy.warn_hours_left) || 24;
const rows = $input.all().map(i => i.json).filter(r => r && r.breach_id);
const now = Date.now();
const open = [];
for (const r of rows) {
  const verdict = String(r.verdict || '');
  if (verdict !== 'NOTIFY_AUTHORITY' && verdict !== 'NOTIFY_AUTHORITY_AND_SUBJECTS') continue;
  if (String(r.authority_notified || 'no').toLowerCase() === 'yes') continue;
  const dl = new Date(String(r.deadline_at || ''));
  if (isNaN(dl.getTime())) {
    open.push({ breach_id: r.breach_id, title: r.title, verdict, deadline_at: String(r.deadline_at || ''), hours_left: 0, state: 'no deadline' });
    continue;
  }
  const hoursLeft = Math.round(((dl.getTime() - now) / 3600000) * 10) / 10;
  let state;
  if (hoursLeft < 0) state = 'overdue';
  else if (hoursLeft <= warnAt) state = 'due soon';
  else state = 'running';
  open.push({ breach_id: r.breach_id, title: r.title, verdict, deadline_at: dl.toISOString(), hours_left: hoursLeft, state });
}
const due = open.filter(o => o.state === 'overdue' || o.state === 'due soon' || o.state === 'no deadline');
due.sort((a, b) => a.hours_left - b.hours_left);
const overdue = due.filter(o => o.state === 'overdue').length;
const lines = due.map(o => '- ' + o.title + ' (' + o.breach_id + ') ' + o.state + ', ' + o.hours_left + ' h left, deadline ' + o.deadline_at);
const summary = due.length
  ? due.length + ' breach(es) still not reported to the authority, ' + overdue + ' past the deadline:\n' + lines.join('\n')
  : (open.length
      ? 'No breach is within ' + warnAt + ' hours of its deadline. ' + open.length + ' notifiable breach(es) are still open with time remaining.'
      : 'No notifiable breach is waiting to be reported. This counts only rows already assessed by this workflow; a breach nobody reported is invisible here.');
return [{
  json: {
    checked_at: new Date().toISOString(), rows_read: rows.length, open_count: open.length,
    due_count: due.length, overdue_count: overdue, warn_hours_left: warnAt,
    needs_attention: due.length > 0, summary, due
  }
}];

const d = $('Check The Deadlines').first().json;
const runId = String($execution.id);
if (!d.due.length) return [{ json: {
  reminder_id: runId, sent_at: d.checked_at, breach_id: 'none', title: 'nothing due',
  verdict: 'none', deadline_at: '', hours_left: 0, state: 'quiet',
  note: 'checked ' + d.rows_read + ' register rows, ' + d.open_count + ' notifiable and still open' } }];
return d.due.map(o => ({ json: {
  reminder_id: runId, sent_at: d.checked_at, breach_id: String(o.breach_id), title: String(o.title),
  verdict: o.verdict, deadline_at: o.deadline_at, hours_left: o.hours_left, state: o.state,
  note: 'reminder sent because the breach is ' + o.state + ' and authority_notified is not yes' } }));
